int main() {
  int calls = 0;
  std::vector<int> xs{1, 2, 3, 4};
  auto r = xs | std::views::transform([&](int x) { ++calls; return x * x; })
              | std::views::filter([](int x) { return x % 2 == 0; });
  for (int x : r) (void)x;
  std::printf("%d\n", calls);
}

