#include <cstdio>
#include <ranges>
#include <vector>

void print(const auto& r) { for (int x : r) std::printf("%d ", x); }

int main() {
  std::vector<int> xs{1, 2, 3};
  print(xs | std::views::transform([](int x) { return x + 1; }));  // 1
  print(xs | std::views::filter([](int x) { return x > 1; }));     // 2
  print(xs | std::views::take(2));                                 // 3
}

